const jsonPrices=value=>{const found=[];if(Array.isArray(value)){for(const item of value)found.push(...jsonPrices(item));return found;}if(!value||typeof value!=='object')return found;const offers=value.offers;if(offers){for(const offer of Array.isArray(offers)?offers:[offers]){const currency=String(offer?.priceCurrency||value.priceCurrency||'').toUpperCase(),price=finitePrice(offer?.price??offer?.lowPrice);if(price!==null&&(!currency||currency==='AED'))found.push(price);}}for(const item of Object.values(value))if(item&&typeof item==='object'&&item!==offers)found.push(...jsonPrices(item));return found;};
