  productProfiles(){return this.database.prepare('SELECT business_id businessId,display_name displayName,category,website_url websiteUrl,actual_price_fils actualPriceFils,actual_price_checked_at actualPriceCheckedAt,pending_price_fils pendingPriceFils,pending_price_detected_at pendingPriceDetectedAt,source_cost_text sourceCost,suggested_price_text suggestedPrice,inventory_status inventoryStatus,inventory_checked_at inventoryCheckedAt,chat_enabled chatEnabled,image_paths imagePaths,updated_at updatedAt FROM product_profiles ORDER BY business_id').all().map(row=>({...row,chatEnabled:Boolean(row.chatEnabled),imagePaths:JSON.parse(row.imagePaths||'[]')}));}
