  dailyProfit(payload={}){const day=isoDay(payload.day),dashboard=this.profitDashboard({}),daily=dashboard.rows.find(row=>row.day===day)||{day,orders:0,remittanceCnyFen:0,shippingAedFils:0,shippingCnyFen:0,adUsdCents:0,usdCnyRateScaled:7200000,adCostCnyFen:0,accountCostCnyFen:0,realProfitCnyFen:0,signedOrders:0,refusedOrders:0,pendingRemittanceOrders:0},orders=this.database.prepare(`SELECT o.id,o.fixed_sequence sequence,o.shopplus_order_no orderNo,COALESCE(o.customer_full_name,o.customer_first_name,'') customerName,COALESCE((SELECT override_value FROM order_recipient_overrides ro WHERE ro.order_id=o.id AND ro.field_name='phone'),o.customer_phone) phone,o.order_total orderAedFils,COALESCE(o.net_remittance,0) remittanceCnyFen,COALESCE((SELECT SUM(p.shipping_fee) FROM packages p WHERE p.order_id=o.id AND p.shipping_fee_finalized=1),0) shippingAedFils,(SELECT GROUP_CONCAT(i.sku_code) FROM order_items i WHERE i.order_id=o.id) products FROM orders o WHERE o.entry_state='active' AND NOT EXISTS(SELECT 1 FROM order_lifecycle l WHERE l.order_id=o.id AND l.state<>'active') AND substr(COALESCE(o.workflow_completed_at,o.remittance_registered_at,o.shopplus_created_at,o.created_at),1,10)=? ORDER BY o.fixed_sequence`).all(day).map(row=>{const shippingCnyFen=Number((BigInt(row.shippingAedFils||0)*180n+50n)/100n);return {...row,sequence:Number(row.sequence),orderAedFils:fils(row.orderAedFils),remittanceCnyFen:Number(row.remittanceCnyFen||0),shippingAedFils:Number(row.shippingAedFils||0),shippingCnyFen,contributionCnyFen:Number(row.remittanceCnyFen||0)-shippingCnyFen,products:String(row.products||'').split(',').filter(Boolean)};});return {day,daily,orders,aedCnyRate:1.8};}
